// Query Classifier — rule-based intent detection with confidence scoring
// Categories: 'vector' (semantic/conceptual), 'kg' (structured/entity), 'hybrid' (both)

const query = $input.first().json.body?.query || $input.first().json.query || '';
const intentHint = $input.first().json.body?.intent_hint || $input.first().json.intent_hint || null;
const topK = $input.first().json.body?.top_k || $input.first().json.top_k || 5;
const conversationId = $input.first().json.body?.conversation_id || $input.first().json.conversation_id || null;
const classifyStart = Date.now();

// If caller provides an intent hint, use it directly
if (intentHint && ['vector', 'kg', 'hybrid'].includes(intentHint)) {
  return [{ json: {
    query, intent: intentHint, confidence: 1.0,
    top_k: topK, conversation_id: conversationId,
    pipeline_start: classifyStart, classify_ms: 0
  }}];
}

const q = query.toLowerCase();

// KG indicators: specific property lookups, product names, CAS numbers, safety data
const kgPatterns = [
  /viscosity|density|molecular weight|boiling point|flash point|melting point|specific gravity/,
  /cas\s*(?:number|#|no)/i,
  /safety|hazard|ppe|first aid|toxicity|storage/,
  /\b(?:dca|dce|eca|asa|mhhpa|ddsa|odsa|nma|jp-?10|ap-?6g|cg)\s*\d*/i,
  /formulation|component|ingredient/,
  /identifier|registration/,
  /produced by|manufacturer/
];

// Hybrid indicators: comparisons, relationships, multiple products
const hybridPatterns = [
  /compare|comparison|difference|versus|vs\.?\b/,
  /similar|alternative|substitute|replacement/,
  /related|relationship|family/,
  /which.*(?:product|chemical).*(?:best|suitable|recommend)/,
  /\band\b.*\band\b/
];

// Vector indicators: conceptual, explanatory, open-ended
const vectorPatterns = [
  /how\s+(?:does|do|is|are|can|should)/,
  /what\s+(?:is|are)\s+(?:a|an|the)?\s*(?!viscosity|density|molecular)/,
  /explain|describe|overview|summary|tell me about/,
  /why|when|application|use case|benefit/,
  /process|mechanism|reaction|cure|crosslink/
];

const kgScore = kgPatterns.filter(p => p.test(q)).length;
const hybridScore = hybridPatterns.filter(p => p.test(q)).length;
const vectorScore = vectorPatterns.filter(p => p.test(q)).length;
const totalMatches = kgScore + hybridScore + vectorScore;

let intent = 'hybrid';
let confidence = 0.5;

if (hybridScore > 0 && kgScore > 0) {
  intent = 'hybrid';
  confidence = Math.min(1.0, (hybridScore + kgScore) / Math.max(totalMatches, 1));
} else if (kgScore >= 2) {
  intent = 'kg';
  confidence = Math.min(1.0, kgScore / Math.max(totalMatches, 1));
} else if (kgScore === 1 && vectorScore === 0) {
  intent = 'kg';
  confidence = 0.6;
} else if (vectorScore >= 2 && kgScore === 0) {
  intent = 'vector';
  confidence = Math.min(1.0, vectorScore / Math.max(totalMatches, 1));
} else if (vectorScore > 0 && kgScore === 0 && hybridScore === 0) {
  intent = 'vector';
  confidence = 0.6;
}

const classifyMs = Date.now() - classifyStart;

return [{ json: {
  query, intent, confidence: Math.round(confidence * 100) / 100,
  top_k: topK, conversation_id: conversationId,
  pipeline_start: classifyStart, classify_ms: classifyMs
}}];

// Fuse Vector Results — format vector search output with timing and result counts

const pipelineStart = $('Query Classifier').first().json.pipeline_start || Date.now();
const classifyMs = $('Query Classifier').first().json.classify_ms || 0;
const confidence = $('Query Classifier').first().json.confidence || 0;
const inputData = $input.first().json;

const results = [];

// Parse internal vector search response
if (inputData.results && Array.isArray(inputData.results)) {
  for (const r of inputData.results) {
    results.push({
      content: r.chunk_text || '',
      source: r.product_name || '',
      source_type: 'vector',
      score: r.relevance_score || 0,
      product_name: r.product_name || '',
      metadata: { section: r.section_name, doc_id: r.doc_id, product_id: r.product_id }
    });
  }
}

const totalMs = Date.now() - pipelineStart;

return [{
  json: {
    results,
    metadata: {
      execution_id: $execution.id,
      intent: 'vector',
      classification_confidence: confidence,
      sources_queried: ['vector'],
      timing_ms: { classify: classifyMs, vector: totalMs - classifyMs },
      total_ms: totalMs,
      result_counts: { vector_count: results.length, fused_count: results.length }
    }
  }
}];

// Fuse KG Results — merge KG entity search + Graphiti results with timing

const pipelineStart = $('Query Classifier').first().json.pipeline_start || Date.now();
const classifyMs = $('Query Classifier').first().json.classify_ms || 0;
const confidence = $('Query Classifier').first().json.confidence || 0;
const items = $input.all();
const results = [];
let kgCount = 0;
let graphitiCount = 0;

for (const item of items) {
  const data = item.json;

  // Internal KG search response {entities, profile, count}
  if (data.entities && Array.isArray(data.entities)) {
    for (const entity of data.entities) {
      results.push({
        content: `${entity.label}: ${entity.canonical_name}`,
        source: entity.canonical_name || '',
        source_type: 'kg',
        score: entity.score || 0,
        product_name: entity.canonical_name || '',
        metadata: { id: entity.id, label: entity.label }
      });
      kgCount++;
    }
    // If profile is included, add as a rich context block
    if (data.profile) {
      const p = data.profile;
      const propsText = (p.properties || []).map(prop => `${prop.name}: ${prop.value}${prop.unit ? ' ' + prop.unit : ''}`).join('; ');
      const appsText = (p.applications || []).join(', ');
      const classText = (p.classification || []).join(', ');
      let profileContent = `Product: ${p.product_name}`;
      if (classText) profileContent += `\nClassification: ${classText}`;
      if (appsText) profileContent += `\nApplications: ${appsText}`;
      if (propsText) profileContent += `\nProperties: ${propsText}`;
      if (p.manufacturer) profileContent += `\nManufacturer: ${p.manufacturer}`;

      results.unshift({
        content: profileContent,
        source: p.product_name,
        source_type: 'kg',
        score: 1.0,
        product_name: p.product_name,
        metadata: { type: 'product_profile' }
      });
      kgCount++;
    }
  }

  // Graphiti search response {results: [{fact, ...}]}
  if (data.results && Array.isArray(data.results)) {
    for (const r of data.results) {
      if (r.fact || r.content) {
        results.push({
          content: r.fact || r.content || '',
          source: r.source_description || '',
          source_type: 'graphiti',
          score: r.score || 0,
          product_name: '',
          metadata: { uuid: r.uuid }
        });
        graphitiCount++;
      }
    }
  }
}

const totalMs = Date.now() - pipelineStart;

return [{
  json: {
    results,
    metadata: {
      execution_id: $execution.id,
      intent: 'kg',
      classification_confidence: confidence,
      sources_queried: ['kg', 'graphiti'],
      timing_ms: { classify: classifyMs, kg: totalMs - classifyMs },
      total_ms: totalMs,
      result_counts: { kg_count: kgCount, graphiti_count: graphitiCount, fused_count: results.length }
    }
  }
}];

// Fuse Hybrid Results — merge vector + KG with configurable weights, dedup, rank
// Weights are configurable via workflow static data

const pipelineStart = $('Query Classifier').first().json.pipeline_start || Date.now();
const classifyMs = $('Query Classifier').first().json.classify_ms || 0;
const confidence = $('Query Classifier').first().json.confidence || 0;

// Configurable weights (edit in workflow settings > Static Data)
const staticData = $getWorkflowStaticData('global');
const vectorWeight = staticData.vector_weight ?? 0.6;
const kgWeight = staticData.kg_weight ?? 0.4;

const items = $input.all();
const results = [];
const seen = new Set();
let vectorCount = 0;
let kgCount = 0;

for (const item of items) {
  const data = item.json;

  // Internal vector search response
  if (data.results && Array.isArray(data.results)) {
    for (const r of data.results) {
      if (r.chunk_text) {
        const key = (r.chunk_text || '').substring(0, 100);
        if (!seen.has(key)) {
          seen.add(key);
          results.push({
            content: r.chunk_text,
            source: r.product_name || '',
            source_type: 'vector',
            score: (r.relevance_score || 0) * vectorWeight,
            raw_score: r.relevance_score || 0,
            product_name: r.product_name || '',
            metadata: { section: r.section_name, doc_id: r.doc_id, product_id: r.product_id }
          });
          vectorCount++;
        }
      }
    }
  }

  // Internal KG search response
  if (data.entities && Array.isArray(data.entities)) {
    for (const entity of data.entities) {
      const key = `kg:${entity.id}`;
      if (!seen.has(key)) {
        seen.add(key);
        results.push({
          content: `${entity.label}: ${entity.canonical_name}`,
          source: entity.canonical_name || '',
          source_type: 'kg',
          score: (entity.score || 0) * kgWeight,
          raw_score: entity.score || 0,
          product_name: entity.canonical_name || '',
          metadata: { id: entity.id, label: entity.label }
        });
        kgCount++;
      }
    }
    // Add profile as top result if available
    if (data.profile) {
      const p = data.profile;
      const propsText = (p.properties || []).map(prop => `${prop.name}: ${prop.value}${prop.unit ? ' ' + prop.unit : ''}`).join('; ');
      const appsText = (p.applications || []).join(', ');
      const classText = (p.classification || []).join(', ');
      let profileContent = `Product: ${p.product_name}`;
      if (classText) profileContent += `\nClassification: ${classText}`;
      if (appsText) profileContent += `\nApplications: ${appsText}`;
      if (propsText) profileContent += `\nProperties: ${propsText}`;
      if (p.manufacturer) profileContent += `\nManufacturer: ${p.manufacturer}`;

      results.unshift({
        content: profileContent,
        source: p.product_name,
        source_type: 'kg',
        score: 1.0,
        raw_score: 1.0,
        product_name: p.product_name,
        metadata: { type: 'product_profile' }
      });
      kgCount++;
    }
  }
}

// Sort by weighted score descending
results.sort((a, b) => b.score - a.score);

const totalMs = Date.now() - pipelineStart;

return [{
  json: {
    results,
    metadata: {
      execution_id: $execution.id,
      intent: 'hybrid',
      classification_confidence: confidence,
      sources_queried: ['vector', 'kg'],
      timing_ms: { classify: classifyMs, retrieval: totalMs - classifyMs },
      total_ms: totalMs,
      result_counts: { vector_count: vectorCount, kg_count: kgCount, fused_count: results.length }
    }
  }
}];
